import React from 'react';

const History = () => {
  // Placeholder: For now, show static message. Will be wired to backend events later.
  return (
    <div className="p-8">
      <h2 className="text-xl font-semibold mb-4">History</h2>
      <div className="bg-white p-6 rounded shadow">
        <p className="text-slate-600">No history yet. Upload CVs or run screenings to populate history.</p>
      </div>
    </div>
  );
};

export default History;
